void GetLanguagesDB(std::vector<psLanguageInfo>& language_db)
{
    psLanguageInfo info;

    // Known languages
    for (int j = 0; tabLangData[j].lang != 0; ++j)
    {
      info.Language          = tabLangData[j].lang;
      info.LocaleTag         = tabLangData[j].bcp47tag;
      info.CanonicalName     = tabLangData[j].canonical;
      info.CanonicalRef      = tabLangData[j].canonicalref;
      info.LayoutDirection   = tabLangData[j].layout;
      info.Description       = tabLangData[j].desc;
      info.DescriptionNative = tabLangData[j].descnative;
#ifdef _WIN32
      info.WinLang           = tabLangData[j].winlang;
      info.WinSublang        = tabLangData[j].winsublang;
#endif // _WIN32
      language_db.emplace_back(info);
    }
}
